using Microsoft.EntityFrameworkCore;
using Microsoft.EntityFrameworkCore.Metadata.Builders;
using SprintFlow.Web.Server.Models;

namespace SprintFlow.Web.Server.Data.Configurations;

public class TeamConfiguration : IEntityTypeConfiguration<Team>
{
    public void Configure(EntityTypeBuilder<Team> builder)
    {
        builder.ToTable("Teams");

        builder.HasKey(t => t.TeamId);

        // Generated by the database, as everywhere else: the client cannot supply it, and the value
        // comes back without a UTC offset so the browser cannot shift the displayed day.
        builder.Property(t => t.CreatedDate)
            .IsRequired()
            .HasDefaultValueSql("SYSUTCDATETIME()");

        // One-to-one on a COMPOSITE key, which turns three separate rules into database rules:
        //   * the foreign key names the board and its creator together, so a team whose owner is
        //     not that board's creator cannot be stored at all;
        //   * the unique index below stops a board gaining a second team;
        //   * the key is one value pair, so a team has nowhere to record a second board.
        // Cascade because a team cannot outlive the board it belongs to.
        builder.HasOne(t => t.Board)
            .WithOne(b => b.Team)
            .HasPrincipalKey<Board>(b => new { b.BoardId, b.CreatedByUserId })
            .HasForeignKey<Team>(t => new { t.BoardId, t.CreatedByUserId })
            .OnDelete(DeleteBehavior.Cascade);

        // Stated explicitly rather than relying on the relationship's own index, so "one team per
        // board" stays readable on its own.
        builder.HasIndex(t => t.BoardId)
            .IsUnique();

        // Restrict, like everywhere else: removing a user must never delete their work.
        builder.HasOne(t => t.CreatedByUser)
            .WithMany()
            .HasForeignKey(t => t.CreatedByUserId)
            .OnDelete(DeleteBehavior.Restrict);
    }
}
